CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY, name TEXT NOT NULL, pc_hash TEXT NOT NULL, mobile_hash TEXT, pair_code TEXT UNIQUE, pair_expires INTEGER, last_seen INTEGER NOT NULL DEFAULT 0, parallel_ready INTEGER NOT NULL DEFAULT 0, wake_config TEXT, power_ready INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES devices(id), payload TEXT, state TEXT NOT NULL, message TEXT NOT NULL, created INTEGER NOT NULL, expires INTEGER NOT NULL, cancel_requested INTEGER NOT NULL DEFAULT 0, batch_id TEXT);
CREATE TRIGGER IF NOT EXISTS max_five_active_jobs BEFORE INSERT ON jobs WHEN (SELECT COUNT(*) FROM jobs WHERE device_id=NEW.device_id AND state IN('queued','claimed','running'))>=5 BEGIN SELECT RAISE(ABORT,'maximum active jobs'); END;
CREATE TABLE IF NOT EXISTS limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
-- Databases created before cancellation support also run migrations/001-cancellation.sql.

CREATE TABLE IF NOT EXISTS power_commands(id TEXT PRIMARY KEY,device_id TEXT NOT NULL REFERENCES devices(id),state TEXT NOT NULL,created INTEGER NOT NULL,expires INTEGER NOT NULL,deadline INTEGER,message TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS no_jobs_during_power BEFORE INSERT ON jobs WHEN EXISTS(SELECT 1 FROM power_commands WHERE device_id=NEW.device_id AND state IN('queued','scheduled','executed') AND expires>CAST(strftime('%s','now') AS INTEGER)*1000) BEGIN SELECT RAISE(ABORT,'PC shutting down'); END;
CREATE TRIGGER IF NOT EXISTS no_shutdown_during_jobs BEFORE INSERT ON power_commands WHEN EXISTS(SELECT 1 FROM jobs WHERE device_id=NEW.device_id AND state IN('queued','claimed','running')) OR EXISTS(SELECT 1 FROM power_commands WHERE device_id=NEW.device_id AND state IN('queued','scheduled','executed') AND expires>CAST(strftime('%s','now') AS INTEGER)*1000) BEGIN SELECT RAISE(ABORT,'PC busy'); END;
